use alloc::vec;

use crate::factor_extract::{extract, FactorCarrier};
use crate::hadamard_factor_bridge::HadamardDescent;
use crate::hadamard_gate::{HadamardCarrier, Tape};
use crate::morphism_factor::{add, divmod, gcd, mul, one, sub, tape_u64, trim, zero};
use crate::vox::{EVALF, EVALT};

#[derive(Clone, Copy)]
struct WidthCase {
    p_bits: usize,
    q_bits: usize,
    p: &'static str,
    q: &'static str,
}

const WIDTH_CASES: [WidthCase; 7] = [
    WidthCase { p_bits: 64, q_bits: 2048, p: "9223372036855282907", q: "" },
    WidthCase { p_bits: 256, q_bits: 1792, p: "57896044618670823160868708949909543709652662193999984418976600496307903136499", q: "" },
    WidthCase { p_bits: 512, q_bits: 1536, p: "6703903964974245550102411630542965371838336179640937573672548683865606029716410353523360886066484305138732165589169587305043019906382808024577115913455619", q: "" },
    WidthCase { p_bits: 768, q_bits: 1280, p: "776259046150866325844365904422158474707460757557377138314579910280021658427681427850792698411405771713857175171621029820091169612298863211725888567280414657794587224727547918037853955048011757522514294714631114483287158479621460603", q: "" },
    WidthCase { p_bits: 1024, q_bits: 1024, p: "", q: "" },
    WidthCase { p_bits: 1024, q_bits: 2048, p: "", q: "" },
    WidthCase { p_bits: 2048, q_bits: 2048, p: "", q: "" },
];

fn decimal_tape(text: &str) -> Tape {
    let ten = tape_u64(10);
    let mut value = vec![EVALT];
    for byte in text.bytes() {
        assert!(byte.is_ascii_digit());
        value = add(&mul(&value, &ten), &tape_u64(u64::from(byte - b'0')));
    }
    trim(value)
}

fn power_of_two_tape(exponent: usize) -> Tape {
    let mut tape = vec![EVALT; exponent + 1];
    tape[exponent] = EVALF;
    tape
}

fn lcm_tape(left: &[char], right: &[char]) -> Tape {
    let g = gcd(left.to_vec(), right.to_vec());
    let (quotient, remainder) = divmod(left, &g);
    assert!(zero(&remainder));
    mul(&quotient, right)
}

fn phase_sample(period: &[char], n_bits: usize) -> (Tape, Tape) {
    let m = power_of_two_tape(2 * n_bits + 2);
    let (k, _) = divmod(&m, period);
    (k, m)
}

fn extracted_pair(carrier: FactorCarrier) -> (Tape, Tape) {
    let readout = extract(&carrier).unwrap();
    assert_eq!(readout.transforms, 0);
    (readout.p.0, readout.q.0)
}

fn run_width_case(case: &WidthCase) {
    let p = decimal_tape(case.p);
    let q = decimal_tape(case.q);
    assert_eq!(p.len(), case.p_bits);
    assert_eq!(q.len(), case.q_bits);

    let n = mul(&p, &q);
    let p_minus = sub(&p, &one());
    let q_minus = sub(&q, &one());
    let period = lcm_tape(&p_minus, &q_minus);
    let (k, m) = phase_sample(&period, n.len());

    let seed = HadamardCarrier::new(&n).unwrap();
    assert_eq!(seed.n(), n.as_slice());
    assert_eq!(seed.source(), [EVALT]);

    let carrier = match seed.descend_phase_sample(&tape_u64(2), &k, &m) {
        HadamardDescent::T(carrier) => carrier,
        other => panic!(
            "{}x{}-bit semiprime failed to close from one phase sample: {other:?}",
            case.p_bits, case.q_bits
        ),
    };

    let (got_p, got_q) = extracted_pair(carrier);
    let direct = got_p == p && got_q == q;
    let swapped = got_p == q && got_q == p;
    assert!(
        direct || swapped,
        "{}x{}-bit factor geometry mismatch",
        case.p_bits,
        case.q_bits
    );
}

#[test]
fn one_phase_sample_spans_factor_width_ratios_at_two_kilobits() {
    for case in &WIDTH_CASES[..5] {
        run_width_case(case);
    }
}

#[test]
fn one_phase_sample_grows_beyond_two_kilobits_with_unrelated_prime_factors() {
    for case in &WIDTH_CASES[5..] {
        run_width_case(case);
    }
}
